SELECT 

WHERE a.deleted = 0

    AND a.org_id = #{scopeOrgId}


    AND a.status <> 'DRAFT'


    AND a.title ILIKE CONCAT('%', #{q.keyword}, '%')


    AND c.category_name = #{q.type}


    AND a.status = #{q.status}


    AND a.org_id = #{q.orgId}


    AND a.status = 'PUBLISHED'
    AND (a.max_count <= 0 OR a.signed_count < a.max_count)

ORDER BY a.id DESC
